DO $$ BEGIN
  CREATE TYPE content_status AS ENUM ('Draft','Published','Archived');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS public.colleges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,name text NOT NULL,short_name text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',page_summary text,city text NOT NULL DEFAULT '',state text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',type text NOT NULL DEFAULT '',image text NOT NULL DEFAULT '',logo text NOT NULL DEFAULT '',meta_title text NOT NULL DEFAULT '',meta_description text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,priority integer NOT NULL DEFAULT 50,short_id bigint GENERATED BY DEFAULT AS IDENTITY,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',page_summary text,category text NOT NULL DEFAULT '',level text NOT NULL DEFAULT '',duration text NOT NULL DEFAULT '',image text NOT NULL DEFAULT '',meta_title text NOT NULL DEFAULT '',meta_description text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,priority integer NOT NULL DEFAULT 50,short_id bigint GENERATED BY DEFAULT AS IDENTITY,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',page_summary text,category text NOT NULL DEFAULT '',level text NOT NULL DEFAULT '',exam_date text NOT NULL DEFAULT '',image text NOT NULL DEFAULT '',logo text NOT NULL DEFAULT '',meta_title text NOT NULL DEFAULT '',meta_description text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,priority integer NOT NULL DEFAULT 50,short_id bigint GENERATED BY DEFAULT AS IDENTITY,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',content text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',featured_image text NOT NULL DEFAULT '',meta_title text NOT NULL DEFAULT '',meta_description text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,priority integer NOT NULL DEFAULT 50,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.career_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',short_description text NOT NULL DEFAULT '',page_summary text,image text NOT NULL DEFAULT '',meta_title text NOT NULL DEFAULT '',meta_description text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,display_order integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,is_featured boolean NOT NULL DEFAULT false,display_order integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.scholarships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,display_order integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_colleges_public_sort ON public.colleges(priority DESC,updated_at DESC) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_courses_public_sort ON public.courses(priority DESC,updated_at DESC) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_exams_public_sort ON public.exams(priority DESC,updated_at DESC) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_articles_public_sort ON public.articles(priority DESC,updated_at DESC) WHERE is_active;
